export const CLIENT_PORTAL_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>NB Finserve — Client Document & Application Portal</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --bg: #F8FAFC;\n      --card-bg: #FFFFFF;\n      --card-border: #E2E8F0;\n      --card-border-focus: #CBD5E1;\n      --primary: #D97706;\n      --primary-hover: #B45309;\n      --primary-gradient: linear-gradient(135deg, #F59E0B 0%, #D97706 100%);\n      --accent: #059669;\n      --accent-light: #ECFDF5;\n      --text: #0F172A;\n      --text-muted: #64748B;\n      --input-bg: #FFFFFF;\n      --input-border: #CBD5E1;\n      --danger: #DC2626;\n      --card-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.05), 0 8px 10px -6px rgba(15, 23, 42, 0.03);\n      --card-shadow-hover: 0 20px 30px -10px rgba(15, 23, 42, 0.08);\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      font-family: 'Plus Jakarta Sans', -apple-system, sans-serif;\n    }\n\n    body {\n      background: var(--bg);\n      background-image: \n        radial-gradient(at 0% 0%, rgba(245, 158, 11, 0.05) 0px, transparent 45%),\n        radial-gradient(at 100% 100%, rgba(16, 185, 129, 0.04) 0px, transparent 45%);\n      color: var(--text);\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      padding: 24px 16px 80px;\n    }\n\n    .container {\n      width: 100%;\n      max-width: 820px;\n      margin: 0 auto;\n    }\n\n    /* Header */\n    .brand-header {\n      text-align: center;\n      padding: 24px 0 32px;\n    }\n\n    .brand-logo-badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 10px;\n      padding: 8px 20px;\n      background: #FEF3C7;\n      border: 1px solid #FDE68A;\n      border-radius: 9999px;\n      margin-bottom: 14px;\n    }\n\n    .brand-logo-icon {\n      width: 20px;\n      height: 20px;\n      fill: var(--primary);\n    }\n\n    .brand-logo-text {\n      font-size: 13px;\n      font-weight: 800;\n      letter-spacing: 1.5px;\n      color: #B45309;\n      text-transform: uppercase;\n    }\n\n    .brand-title {\n      font-size: 28px;\n      font-weight: 800;\n      color: #0F172A;\n      letter-spacing: -0.5px;\n      margin-bottom: 6px;\n    }\n\n    .brand-subtitle {\n      font-size: 14.5px;\n      color: var(--text-muted);\n    }\n\n    /* Card styling */\n    .portal-card {\n      background: var(--card-bg);\n      border: 1px solid var(--card-border);\n      border-radius: 18px;\n      padding: 32px;\n      box-shadow: var(--card-shadow);\n      margin-bottom: 22px;\n      transition: all 0.25s ease;\n    }\n\n    .portal-card:hover {\n      box-shadow: var(--card-shadow-hover);\n    }\n\n    .portal-card-header {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      margin-bottom: 22px;\n      padding-bottom: 16px;\n      border-bottom: 1px solid #F1F5F9;\n    }\n\n    .portal-card-icon {\n      font-size: 22px;\n    }\n\n    .portal-card-title {\n      font-size: 18px;\n      font-weight: 800;\n      color: #0F172A;\n    }\n\n    /* Inputs & Form */\n    .form-group {\n      margin-bottom: 20px;\n    }\n\n    .form-label {\n      display: block;\n      font-size: 12px;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n      color: #475569;\n      margin-bottom: 8px;\n    }\n\n    .input-wrapper {\n      position: relative;\n      display: flex;\n      align-items: center;\n    }\n\n    .input-prefix {\n      position: absolute;\n      left: 16px;\n      color: #64748B;\n      font-weight: 700;\n      font-size: 15px;\n    }\n\n    .form-input {\n      width: 100%;\n      background: var(--input-bg);\n      border: 1.5px solid var(--input-border);\n      border-radius: 12px;\n      padding: 13px 16px;\n      font-size: 15px;\n      color: var(--text);\n      outline: none;\n      transition: all 0.2s ease;\n    }\n\n    .form-input:focus {\n      border-color: var(--primary);\n      box-shadow: 0 0 0 3px rgba(217, 119, 6, 0.15);\n    }\n\n    .form-input.has-prefix {\n      padding-left: 54px;\n    }\n\n    .form-input:disabled, .form-input[readonly] {\n      background: #F1F5F9;\n      color: #64748B;\n      border-color: #E2E8F0;\n      cursor: not-allowed;\n    }\n\n    /* Buttons */\n    .btn {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      width: 100%;\n      padding: 14px 22px;\n      font-size: 15px;\n      font-weight: 700;\n      border-radius: 12px;\n      cursor: pointer;\n      border: none;\n      transition: all 0.2s ease;\n    }\n\n    .btn-primary {\n      background: var(--primary-gradient);\n      color: #FFFFFF;\n      box-shadow: 0 4px 14px rgba(217, 119, 6, 0.25);\n    }\n\n    .btn-primary:hover {\n      opacity: 0.95;\n      transform: translateY(-1px);\n      box-shadow: 0 6px 18px rgba(217, 119, 6, 0.35);\n    }\n\n    .btn-secondary {\n      background: #F8FAFC;\n      color: #334155;\n      border: 1.5px solid #CBD5E1;\n    }\n\n    .btn-secondary:hover {\n      background: #F1F5F9;\n      border-color: #94A3B8;\n    }\n\n    .btn:disabled {\n      opacity: 0.55;\n      cursor: not-allowed;\n      transform: none !important;\n    }\n\n    /* OTP Inputs */\n    .otp-container {\n      display: flex;\n      justify-content: center;\n      gap: 12px;\n      margin: 24px 0;\n    }\n\n    .otp-input {\n      width: 50px;\n      height: 58px;\n      text-align: center;\n      font-size: 24px;\n      font-weight: 800;\n      font-family: 'JetBrains Mono', monospace;\n      background: #FFFFFF;\n      border: 2px solid #CBD5E1;\n      border-radius: 12px;\n      color: #0F172A;\n      outline: none;\n      transition: all 0.2s;\n    }\n\n    .otp-input:focus {\n      border-color: var(--primary);\n      box-shadow: 0 0 0 3px rgba(217, 119, 6, 0.15);\n    }\n\n    /* Alerts */\n    .alert {\n      padding: 14px 18px;\n      border-radius: 12px;\n      font-size: 14px;\n      line-height: 1.5;\n      margin-bottom: 20px;\n      display: flex;\n      align-items: flex-start;\n      gap: 12px;\n    }\n\n    .alert-info {\n      background: #EFF6FF;\n      border: 1px solid #BFDBFE;\n      color: #1E40AF;\n    }\n\n    .alert-success {\n      background: #ECFDF5;\n      border: 1px solid #A7F3D0;\n      color: #065F46;\n    }\n\n    .alert-danger {\n      background: #FEF2F2;\n      border: 1px solid #FECACA;\n      color: #991B1B;\n    }\n\n    /* Application Details Grid */\n    .details-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));\n      gap: 16px;\n    }\n\n    .detail-item {\n      background: #F8FAFC;\n      border: 1px solid #E2E8F0;\n      border-radius: 12px;\n      padding: 12px 16px;\n    }\n\n    .detail-item.full-width {\n      grid-column: 1 / -1;\n    }\n\n    .detail-label {\n      font-size: 11px;\n      font-weight: 700;\n      color: var(--text-muted);\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n      margin-bottom: 4px;\n    }\n\n    .detail-value {\n      font-size: 14.5px;\n      font-weight: 700;\n      color: #0F172A;\n      word-break: break-word;\n    }\n\n    /* Documents list */\n    .doc-item-card {\n      background: #FFFFFF;\n      border: 1px solid var(--card-border);\n      border-radius: 14px;\n      padding: 16px 20px;\n      margin-bottom: 14px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n      flex-wrap: wrap;\n      transition: all 0.2s;\n    }\n\n    .doc-item-card:hover {\n      border-color: #CBD5E1;\n      box-shadow: 0 4px 12px rgba(15, 23, 42, 0.04);\n    }\n\n    .doc-item-info {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n      min-width: 250px;\n      flex: 1;\n    }\n\n    .doc-item-icon {\n      width: 44px;\n      height: 44px;\n      border-radius: 12px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 20px;\n      background: #F1F5F9;\n      color: var(--text-muted);\n    }\n\n    .doc-item-icon.uploaded {\n      background: #D1FAE5;\n      color: var(--accent);\n    }\n\n    .doc-item-title {\n      font-size: 15px;\n      font-weight: 700;\n      color: #0F172A;\n      margin-bottom: 3px;\n    }\n\n    .doc-item-meta {\n      font-size: 12.5px;\n      color: var(--text-muted);\n    }\n\n    .badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 4px;\n      padding: 5px 12px;\n      font-size: 11.5px;\n      font-weight: 800;\n      border-radius: 6px;\n      text-transform: uppercase;\n      letter-spacing: 0.5px;\n    }\n\n    .badge-uploaded {\n      background: #D1FAE5;\n      color: #065F46;\n      border: 1px solid #A7F3D0;\n    }\n\n    .badge-pending {\n      background: #FEF3C7;\n      color: #92400E;\n      border: 1px solid #FDE68A;\n    }\n\n    .doc-upload-btn-wrap {\n      position: relative;\n    }\n\n    .doc-upload-input {\n      position: absolute;\n      left: 0;\n      top: 0;\n      opacity: 0;\n      width: 100%;\n      height: 100%;\n      cursor: pointer;\n    }\n\n    .btn-sm {\n      padding: 8px 16px;\n      font-size: 13.5px;\n      border-radius: 9px;\n      width: auto;\n    }\n\n    /* Toast */\n    #toast {\n      position: fixed;\n      bottom: 28px;\n      left: 50%;\n      transform: translateX(-50%) translateY(120px);\n      background: #0F172A;\n      border: 1px solid rgba(255, 255, 255, 0.15);\n      color: #FFFFFF;\n      padding: 13px 26px;\n      border-radius: 12px;\n      font-size: 14.5px;\n      font-weight: 600;\n      box-shadow: 0 12px 30px rgba(0,0,0,0.25);\n      transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n      z-index: 9999;\n      opacity: 0;\n      pointer-events: none;\n      max-width: 90%;\n      text-align: center;\n    }\n\n    #toast.show {\n      transform: translateX(-50%) translateY(0);\n      opacity: 1;\n    }\n\n    .spinner {\n      display: inline-block;\n      width: 16px;\n      height: 16px;\n      border: 2px solid rgba(255,255,255,0.4);\n      border-radius: 50%;\n      border-top-color: #FFFFFF;\n      animation: spin 0.8s linear infinite;\n    }\n\n    @keyframes spin {\n      to { transform: rotate(360deg); }\n    }\n\n    /* Progress bar */\n    .progress-bar-wrap {\n      width: 100%;\n      height: 8px;\n      background: #E2E8F0;\n      border-radius: 4px;\n      overflow: hidden;\n      margin: 14px 0 22px;\n    }\n\n    .progress-bar-fill {\n      height: 100%;\n      background: linear-gradient(90deg, #10B981, #059669);\n      width: 0%;\n      transition: width 0.4s ease;\n    }\n\n    /* Responsive */\n    @media (max-width: 600px) {\n      .portal-card {\n        padding: 24px 20px;\n      }\n      .brand-title {\n        font-size: 24px;\n      }\n      .otp-input {\n        width: 44px;\n        height: 52px;\n        font-size: 20px;\n      }\n      .doc-item-card {\n        flex-direction: column;\n        align-items: stretch;\n      }\n      .doc-item-actions {\n        display: flex;\n        justify-content: flex-end;\n      }\n    }\n  </style>\n</head>\n<body>\n\n  <div class=\"container\">\n    <!-- Brand Header -->\n    <div class=\"brand-header\">\n      <div class=\"brand-logo-badge\">\n        <svg class=\"brand-logo-icon\" viewBox=\"0 0 24 24\">\n          <path d=\"M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5\"></path>\n        </svg>\n        <span class=\"brand-logo-text\">NB Finserve</span>\n      </div>\n      <h1 class=\"brand-title\">Client Application & Document Portal</h1>\n      <p class=\"brand-subtitle\">Financial Services • Secure Identity Verification • Loan File Processing</p>\n    </div>\n\n    <!-- Step 1: Mobile Number Verification Card -->\n    <div id=\"step-mobile-card\" class=\"portal-card\">\n      <div class=\"portal-card-header\">\n        <span class=\"portal-card-icon\">🔒</span>\n        <h2 class=\"portal-card-title\">Step 1: Confirm Your Identity</h2>\n      </div>\n\n      <div id=\"applicant-greeting-badge\" style=\"display: none; align-items: center; gap: 8px; padding: 10px 16px; background: #FEF3C7; border: 1px solid #FDE68A; border-radius: 10px; margin-bottom: 18px; font-weight: 700; color: #92400E; font-size: 14px;\">\n        <span>👤</span>\n        <span id=\"applicant-greeting-name\">Applicant Name</span>\n      </div>\n\n      <p style=\"font-size: 14.5px; color: var(--text-muted); margin-bottom: 22px; line-height: 1.6;\">\n        Welcome to your loan document portal. Please enter your registered 10-digit mobile number to verify your identity. A secure one-time passcode will be sent to your registered email.\n      </p>\n\n      <div class=\"form-group\">\n        <label class=\"form-label\" for=\"input-mobile\">Registered Mobile Number</label>\n        <div class=\"input-wrapper\">\n          <span class=\"input-prefix\">+91</span>\n          <input type=\"tel\" id=\"input-mobile\" class=\"form-input has-prefix\" placeholder=\"Enter 10-digit mobile number\" maxlength=\"16\" autofocus>\n        </div>\n        <p id=\"phone-hint-text\" style=\"display: none; font-size: 13px; color: #64748B; margin-top: 8px;\">\n          Registered with: <strong id=\"phone-hint-val\" style=\"color: #0F172A;\"></strong>\n        </p>\n      </div>\n\n      <div id=\"step-mobile-error\" class=\"alert alert-danger\" style=\"display: none; margin-bottom: 18px;\"></div>\n\n      <button id=\"btn-send-otp\" class=\"btn btn-primary\">\n        <span>Send Verification Code</span>\n      </button>\n    </div>\n\n    <!-- Step 2: Email OTP Card -->\n    <div id=\"step-otp-card\" class=\"portal-card\" style=\"display: none;\">\n      <div class=\"portal-card-header\">\n        <span class=\"portal-card-icon\">✉️</span>\n        <h2 class=\"portal-card-title\">Step 2: Enter Email Verification Code</h2>\n      </div>\n\n      <div class=\"alert alert-info\">\n        <span>📧 Verification code sent to: <strong id=\"masked-email-display\">your email</strong>. Please check your inbox and enter the 6-digit code below.</span>\n      </div>\n\n      <div id=\"step-otp-error\" class=\"alert alert-danger\" style=\"display: none; margin-bottom: 18px;\"></div>\n\n      <div class=\"otp-container\">\n        <input type=\"text\" class=\"otp-input\" maxlength=\"1\" pattern=\"[0-9]\" inputmode=\"numeric\">\n        <input type=\"text\" class=\"otp-input\" maxlength=\"1\" pattern=\"[0-9]\" inputmode=\"numeric\">\n        <input type=\"text\" class=\"otp-input\" maxlength=\"1\" pattern=\"[0-9]\" inputmode=\"numeric\">\n        <input type=\"text\" class=\"otp-input\" maxlength=\"1\" pattern=\"[0-9]\" inputmode=\"numeric\">\n        <input type=\"text\" class=\"otp-input\" maxlength=\"1\" pattern=\"[0-9]\" inputmode=\"numeric\">\n        <input type=\"text\" class=\"otp-input\" maxlength=\"1\" pattern=\"[0-9]\" inputmode=\"numeric\">\n      </div>\n\n      <button id=\"btn-verify-otp\" class=\"btn btn-primary\">\n        <span>Verify Code & View Application</span>\n      </button>\n\n      <div style=\"text-align: center; margin-top: 22px;\">\n        <button id=\"btn-resend-otp\" class=\"btn btn-secondary btn-sm\">Resend Code</button>\n        <div id=\"resend-timer-text\" style=\"font-size: 12.5px; color: var(--text-muted); margin-top: 8px;\"></div>\n        <div id=\"resend-limit-warning\" class=\"alert alert-danger\" style=\"display: none; margin-top: 14px; text-align: left;\"></div>\n      </div>\n    </div>\n\n    <!-- Step 3: Verified Client Dashboard -->\n    <div id=\"step-dashboard\" style=\"display: none;\">\n      <!-- Welcome summary header card -->\n      <div class=\"portal-card\" style=\"border-left: 5px solid var(--primary);\">\n        <div style=\"display: flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 14px;\">\n          <div>\n            <div style=\"display: flex; align-items: center; gap: 8px; margin-bottom: 4px;\">\n              <h2 id=\"client-name-display\" style=\"font-size: 22px; font-weight: 800; color: #0F172A;\">Applicant Name</h2>\n              <span id=\"portal-status-badge\" class=\"badge badge-uploaded\">✓ VERIFIED</span>\n            </div>\n            <p id=\"client-loan-type-display\" style=\"font-size: 14.5px; color: var(--primary); font-weight: 700;\">Loan Category: Personal Loan</p>\n          </div>\n          <div style=\"text-align: right;\">\n            <div style=\"font-size: 11.5px; text-transform: uppercase; color: var(--text-muted); font-weight: 700;\">Required Loan Amount</div>\n            <div id=\"client-loan-amount-display\" style=\"font-size: 24px; font-weight: 800; color: #059669;\">₹0</div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Locked Status Banner (visible when submitted) -->\n      <div id=\"dashboard-locked-banner\" class=\"alert alert-success\" style=\"display: none; align-items: flex-start; gap: 14px;\">\n        <span style=\"font-size: 22px;\">🔒</span>\n        <div>\n          <div style=\"font-weight: 800; font-size: 15px; margin-bottom: 3px;\">Application Confirmed & Locked</div>\n          <p style=\"font-size: 13.5px; margin: 0; line-height: 1.5;\">\n            Your documents have been submitted and locked for review. Only your NB Finserve loan administrator can modify your file.\n          </p>\n        </div>\n      </div>\n\n      <!-- Notice Alert -->\n      <div id=\"dashboard-notice-alert\" class=\"alert alert-info\">\n        <span>ℹ️ <strong>Application Details (Read Only)</strong>: These details have been recorded by your loan advisor. Please review them and upload the required documents below to process your file.</span>\n      </div>\n\n      <!-- Read-Only Personal Details -->\n      <div class=\"portal-card\">\n        <div class=\"portal-card-header\">\n          <span class=\"portal-card-icon\">🎗️</span>\n          <h3 class=\"portal-card-title\">Personal Details</h3>\n        </div>\n        <div id=\"personal-details-grid\" class=\"details-grid\">\n          <!-- Populated dynamically -->\n        </div>\n      </div>\n\n      <!-- Read-Only Company Details -->\n      <div class=\"portal-card\">\n        <div class=\"portal-card-header\">\n          <span class=\"portal-card-icon\">🏢</span>\n          <h3 class=\"portal-card-title\">Company & Employment Details</h3>\n        </div>\n        <div id=\"company-details-grid\" class=\"details-grid\">\n          <!-- Populated dynamically -->\n        </div>\n      </div>\n\n      <!-- Read-Only Reference Details -->\n      <div class=\"portal-card\">\n        <div class=\"portal-card-header\">\n          <span class=\"portal-card-icon\">👥</span>\n          <h3 class=\"portal-card-title\">Reference Details</h3>\n        </div>\n        <div id=\"reference-details-grid\" class=\"details-grid\">\n          <!-- Populated dynamically -->\n        </div>\n      </div>\n\n      <!-- Required Document Checklist & Upload Section -->\n      <div class=\"portal-card\" style=\"border-top: 4px solid var(--accent);\">\n        <div class=\"portal-card-header\">\n          <span class=\"portal-card-icon\">📁</span>\n          <div style=\"flex: 1;\">\n            <h3 class=\"portal-card-title\">Required Loan Documents Checklist</h3>\n            <p style=\"font-size: 12.5px; color: var(--text-muted); margin-top: 2px;\">\n              Upload clear PDF, JPG or PNG copies for each checklist item within the specified file size limit.\n            </p>\n          </div>\n          <span id=\"doc-counter-badge\" class=\"badge badge-pending\">0 / 0 UPLOADED</span>\n        </div>\n\n        <div class=\"progress-bar-wrap\">\n          <div id=\"doc-progress-fill\" class=\"progress-bar-fill\"></div>\n        </div>\n\n        <div id=\"documents-list-container\">\n          <!-- Populated dynamically -->\n        </div>\n      </div>\n\n      <!-- Step 4: Final Confirmation & Lock Card -->\n      <div id=\"confirmation-card\" class=\"portal-card\" style=\"border: 1.5px solid #CBD5E1;\">\n        <div class=\"portal-card-header\">\n          <span class=\"portal-card-icon\">✍️</span>\n          <h3 class=\"portal-card-title\">Final Confirmation & Submission</h3>\n        </div>\n\n        <div id=\"submission-action-wrap\">\n          <p style=\"font-size: 14px; color: var(--text-muted); margin-bottom: 18px; line-height: 1.6;\">\n            Please ensure you have uploaded all required documents. Once you submit, your application is locked and forwarded to NB Finserve for underwriting. <strong>After submission, you will not be able to modify or replace documents</strong> without contacting your administrator.\n          </p>\n\n          <label style=\"display: flex; align-items: flex-start; gap: 12px; cursor: pointer; padding: 14px 16px; background: #F8FAFC; border: 1.5px solid #E2E8F0; border-radius: 12px; margin-bottom: 20px;\">\n            <input type=\"checkbox\" id=\"confirm-checkbox\" style=\"width: 18px; height: 18px; margin-top: 2px; accent-color: var(--primary); cursor: pointer;\">\n            <span style=\"font-size: 13.5px; color: #334155; line-height: 1.5;\">\n              I confirm that the recorded application details are correct, and all uploaded documents are genuine and complete. I understand that <strong>once saved, documents are locked and only an administrator can change them</strong>.\n            </span>\n          </label>\n\n          <button id=\"btn-submit-portal\" class=\"btn btn-primary\" disabled style=\"opacity: 0.5;\">\n            <span>Save & Submit Application</span>\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div id=\"toast\">Message</div>\n\n  <script>\n    // Robust token extraction from Query Param, Hash, or Path\n    function getPortalToken() {\n      const urlParams = new URLSearchParams(window.location.search);\n      let t = urlParams.get('token');\n      if (t) return t.trim();\n\n      if (window.location.hash) {\n        const hash = window.location.hash;\n        const qIdx = hash.indexOf('?');\n        if (qIdx !== -1) {\n          const hp = new URLSearchParams(hash.substring(qIdx));\n          t = hp.get('token');\n          if (t) return t.trim();\n        }\n        const m = hash.match(/token=([a-zA-Z0-9]+)/);\n        if (m) return m[1].trim();\n      }\n\n      const parts = window.location.pathname.split('/').filter(Boolean);\n      const idx = parts.findIndex(p => p === 'client-portal');\n      if (idx !== -1 && parts[idx + 1] && parts[idx + 1] !== 'index.html') {\n        return parts[idx + 1].trim();\n      }\n\n      return '';\n    }\n\n    // Determine API origin (falls back to local port 4000 if opened on dev port 5000 or similar)\n    function getApiBase() {\n      if (!window.location.port || ['4000', '80', '443'].includes(window.location.port)) {\n        return '';\n      }\n      if (['localhost', '127.0.0.1'].includes(window.location.hostname)) {\n        return 'http://localhost:4000';\n      }\n      return '';\n    }\n\n    const token = getPortalToken();\n    const apiBase = getApiBase();\n\n    // State\n    let currentMobile = '';\n    let applicationData = null;\n    let resendInterval = null;\n    let attemptsRemaining = 3;\n\n    // Toast helper\n    function showToast(msg, isError = false) {\n      const toast = document.getElementById('toast');\n      toast.textContent = msg;\n      toast.style.borderColor = isError ? 'rgba(239, 68, 68, 0.8)' : 'rgba(16, 185, 129, 0.8)';\n      toast.style.background = isError ? '#991B1B' : '#0F172A';\n      toast.classList.add('show');\n      setTimeout(() => toast.classList.remove('show'), 4000);\n    }\n\n    // OTP Input Navigation\n    const otpInputs = document.querySelectorAll('.otp-input');\n    otpInputs.forEach((input, index) => {\n      input.addEventListener('input', (e) => {\n        if (e.target.value.length === 1 && index < otpInputs.length - 1) {\n          otpInputs[index + 1].focus();\n        }\n      });\n      input.addEventListener('keydown', (e) => {\n        if (e.key === 'Enter') {\n          e.preventDefault();\n          verifyOtp();\n        } else if (e.key === 'Backspace' && !e.target.value && index > 0) {\n          otpInputs[index - 1].focus();\n        }\n      });\n      input.addEventListener('paste', (e) => {\n        e.preventDefault();\n        const pasted = e.clipboardData.getData('text').trim();\n        if (/^\\d{6}$/.test(pasted)) {\n          pasted.split('').forEach((ch, i) => {\n            if (otpInputs[i]) otpInputs[i].value = ch;\n          });\n          otpInputs[otpInputs.length - 1].focus();\n        }\n      });\n    });\n\n    function getEnteredOtp() {\n      return Array.from(otpInputs).map(inp => inp.value).join('');\n    }\n\n    // Initialize check\n    async function initPortal() {\n      if (!token) {\n        document.getElementById('step-mobile-card').innerHTML = `\n          <div class=\"alert alert-danger\">\n            <span>⚠️ <strong>Invalid Link</strong>: No application token was found in the URL. Please use the complete link sent by your NB Finserve loan advisor.</span>\n          </div>\n        `;\n        return;\n      }\n\n      try {\n        const res = await fetch(`${apiBase}/api/crm-public/client-portal/${token}/info`);\n        const data = await res.json();\n        if (!res.ok || !data.success) {\n          throw new Error(data.error || 'Invalid or expired link');\n        }\n\n        // Populate greeting badge and registered phone hint\n        if (data.data) {\n          const info = data.data;\n          const greetBadge = document.getElementById('applicant-greeting-badge');\n          const greetName = document.getElementById('applicant-greeting-name');\n          if (greetBadge && greetName && info.leadName) {\n            greetName.textContent = `Welcome, ${info.leadName} (${info.loanType || 'Loan Application'})`;\n            greetBadge.style.display = 'inline-flex';\n          }\n          const hintP = document.getElementById('phone-hint-text');\n          const hintVal = document.getElementById('phone-hint-val');\n          if (hintP && hintVal && info.maskedPhone) {\n            hintVal.textContent = info.maskedPhone;\n            hintP.style.display = 'block';\n          }\n        }\n      } catch (err) {\n        document.getElementById('step-mobile-card').innerHTML = `\n          <div class=\"alert alert-danger\">\n            <span>⚠️ <strong>Link Expired or Invalid</strong>: ${escapeHtml(err.message)}. Please contact your loan advisor for a new link.</span>\n          </div>\n        `;\n      }\n    }\n\n    // Step 1: Send OTP\n    async function sendOtp() {\n      const errBox = document.getElementById('step-mobile-error');\n      if (errBox) { errBox.style.display = 'none'; errBox.textContent = ''; }\n\n      if (!token) {\n        const msg = 'Invalid or missing portal token. Please use the complete link provided.';\n        if (errBox) {\n          errBox.innerHTML = `⚠️ <strong>Error</strong>: ${msg}`;\n          errBox.style.display = 'flex';\n        }\n        showToast(msg, true);\n        return;\n      }\n\n      const mobileInput = document.getElementById('input-mobile');\n      let mobile = (mobileInput.value || '').trim().replace(/\\D/g, '');\n      if (mobile.length > 10) {\n        mobile = mobile.slice(-10);\n      }\n\n      if (mobile.length !== 10) {\n        const msg = 'Please enter your valid 10-digit registered mobile number';\n        if (errBox) {\n          errBox.innerHTML = `⚠️ <strong>Error</strong>: ${msg}`;\n          errBox.style.display = 'flex';\n        }\n        showToast(msg, true);\n        return;\n      }\n\n      const btn = document.getElementById('btn-send-otp');\n      btn.disabled = true;\n      btn.innerHTML = '<span class=\"spinner\"></span> <span>Sending Code...</span>';\n\n      try {\n        const res = await fetch(`${apiBase}/api/crm-public/client-portal/${token}/send-otp`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ mobile }),\n        });\n        const data = await res.json();\n\n        if (!res.ok || !data.success) {\n          throw new Error(data.error || 'Failed to send verification code');\n        }\n\n        currentMobile = mobile;\n        document.getElementById('masked-email-display').textContent = data.data.maskedEmail || 'registered email';\n        document.getElementById('step-mobile-card').style.display = 'none';\n        document.getElementById('step-otp-card').style.display = 'block';\n\n        otpInputs.forEach((inp) => { inp.value = ''; });\n        otpInputs[0].focus();\n\n        if (typeof data.data.attemptsRemaining === 'number') {\n          attemptsRemaining = data.data.attemptsRemaining;\n        }\n\n        startResendTimer(data.data.cooldownSeconds || 30);\n        showToast(data.data.message || 'Verification code sent to your registered email!');\n      } catch (err) {\n        if (errBox) {\n          errBox.innerHTML = `⚠️ <strong>Verification Error</strong>: ${escapeHtml(err.message)}`;\n          errBox.style.display = 'flex';\n        }\n        showToast(err.message, true);\n      } finally {\n        btn.disabled = false;\n        btn.innerHTML = '<span>Send Verification Code</span>';\n      }\n    }\n\n    // Resend Timer with 30s cooldown and 3 attempts per hour rate limit\n    function startResendTimer(seconds) {\n      let cooldown = seconds;\n      const resendBtn = document.getElementById('btn-resend-otp');\n      const timerText = document.getElementById('resend-timer-text');\n      const warningBox = document.getElementById('resend-limit-warning');\n\n      if (resendInterval) clearInterval(resendInterval);\n\n      resendBtn.disabled = true;\n      resendBtn.style.opacity = '0.5';\n\n      function renderCountdown() {\n        resendBtn.textContent = `Resend Code (${cooldown}s)`;\n        timerText.textContent = `Resend available in ${cooldown}s • ${attemptsRemaining} attempt(s) remaining`;\n      }\n\n      renderCountdown();\n\n      resendInterval = setInterval(() => {\n        cooldown--;\n        if (cooldown <= 0) {\n          clearInterval(resendInterval);\n          resendInterval = null;\n          if (attemptsRemaining > 0) {\n            resendBtn.disabled = false;\n            resendBtn.style.opacity = '1';\n            resendBtn.textContent = 'Resend Code';\n            timerText.textContent = `${attemptsRemaining} resend attempt(s) remaining`;\n          } else {\n            resendBtn.disabled = true;\n            resendBtn.style.opacity = '0.5';\n            resendBtn.textContent = 'Resend Limit Reached';\n            timerText.textContent = 'Maximum attempts reached (3/3)';\n            if (warningBox) {\n              warningBox.innerHTML = '⚠️ <strong>Limit Reached</strong>: You have used all 3 verification requests. For security, please try again in 1 hour.';\n              warningBox.style.display = 'flex';\n            }\n          }\n        } else {\n          renderCountdown();\n        }\n      }, 1000);\n    }\n\n    async function resendOtp() {\n      if (!currentMobile) return;\n      const warningBox = document.getElementById('resend-limit-warning');\n      if (warningBox) warningBox.style.display = 'none';\n\n      try {\n        const res = await fetch(`${apiBase}/api/crm-public/client-portal/${token}/send-otp`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ mobile: currentMobile }),\n        });\n        const data = await res.json();\n        if (!res.ok || !data.success) throw new Error(data.error || 'Resend failed');\n\n        otpInputs.forEach((inp) => { inp.value = ''; });\n        otpInputs[0].focus();\n\n        if (typeof data.data.attemptsRemaining === 'number') {\n          attemptsRemaining = data.data.attemptsRemaining;\n        }\n\n        startResendTimer(data.data.cooldownSeconds || 30);\n        showToast(data.data.message || 'New verification code sent to your email!');\n      } catch (err) {\n        showToast(err.message, true);\n        if (err.message && err.message.includes('Maximum')) {\n          if (warningBox) {\n            warningBox.innerHTML = `⚠️ <strong>Limit Reached</strong>: ${escapeHtml(err.message)}`;\n            warningBox.style.display = 'flex';\n          }\n        }\n      }\n    }\n\n    // Step 2: Verify OTP\n    async function verifyOtp() {\n      const errBox = document.getElementById('step-otp-error');\n      if (errBox) { errBox.style.display = 'none'; errBox.textContent = ''; }\n\n      const otp = getEnteredOtp();\n      if (otp.length !== 6) {\n        const msg = 'Please enter all 6 digits of your verification code';\n        if (errBox) {\n          errBox.innerHTML = `⚠️ <strong>Error</strong>: ${msg}`;\n          errBox.style.display = 'flex';\n        }\n        showToast(msg, true);\n        return;\n      }\n\n      const btn = document.getElementById('btn-verify-otp');\n      btn.disabled = true;\n      btn.innerHTML = '<span class=\"spinner\"></span> <span>Verifying...</span>';\n\n      try {\n        const res = await fetch(`${apiBase}/api/crm-public/client-portal/${token}/verify-otp`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ mobile: currentMobile, otp }),\n        });\n        const data = await res.json();\n\n        if (!res.ok || !data.success) {\n          throw new Error(data.error || 'Invalid verification code');\n        }\n\n        applicationData = data.data.lead;\n        renderDashboard(applicationData);\n        document.getElementById('step-otp-card').style.display = 'none';\n        document.getElementById('step-dashboard').style.display = 'block';\n        showToast('Identity verified successfully! Welcome.');\n      } catch (err) {\n        if (errBox) {\n          errBox.innerHTML = `⚠️ <strong>Invalid Code</strong>: ${escapeHtml(err.message)}`;\n          errBox.style.display = 'flex';\n        }\n        showToast(err.message, true);\n      } finally {\n        btn.disabled = false;\n        btn.innerHTML = '<span>Verify Code & View Application</span>';\n      }\n    }\n\n    // Render Dashboard\n    function renderDashboard(lead) {\n      const app = lead.applicationDetails || {};\n      const isSubmitted = lead.isSubmitted || lead.clientPortalStatus === 'SUBMITTED';\n\n      document.getElementById('client-name-display').textContent = lead.name || app.motherName || 'Valued Applicant';\n      document.getElementById('client-loan-type-display').textContent = `Loan Category: ${lead.loanType || 'Personal Loan'}`;\n      \n      const rawAmt = app.requiredLoanAmount || lead.loanAmount || lead.amount || '';\n      const numAmt = Number(String(rawAmt).replace(/[^0-9.]/g, ''));\n      const reqAmount = !isNaN(numAmt) && numAmt > 0 ? `₹${numAmt.toLocaleString('en-IN')}` : (rawAmt ? `₹${rawAmt}` : '—');\n      document.getElementById('client-loan-amount-display').textContent = reqAmount;\n\n      const formatVal = (v) => {\n        if (!v || v === 'None' || v === 'null' || v === 'undefined') return '—';\n        return v;\n      };\n\n      // Personal Details Cards\n      const personalFields = [\n        { label: 'Mobile No', val: formatVal(app.mobileNo || lead.phone) },\n        { label: 'Alternate No', val: formatVal(app.alternateNo) },\n        { label: 'Personal Mail ID', val: formatVal(app.personalEmail) },\n        { label: 'Marital Status', val: formatVal(app.maritalStatus) },\n        { label: 'Mother Name', val: formatVal(app.motherName) },\n        { label: 'Spouse Name', val: formatVal(app.spouseName) },\n        { label: 'Education', val: formatVal(app.education) },\n        { label: 'Current Address', val: formatVal(app.currentAddress), full: true },\n        { label: 'Current Residence Type', val: formatVal(app.currentAddressType) },\n        { label: 'Permanent Address', val: formatVal(app.permanentAddress), full: true },\n        { label: 'Permanent Residence Type', val: formatVal(app.permanentAddressType) },\n        { label: 'Require Loan Amount', val: reqAmount },\n        { label: 'Loan Purpose', val: formatVal(app.loanPurpose || lead.loanType) },\n      ];\n\n      const pGrid = document.getElementById('personal-details-grid');\n      pGrid.innerHTML = personalFields.map(f => `\n        <div class=\"detail-item ${f.full ? 'full-width' : ''}\">\n          <div class=\"detail-label\">${escapeHtml(f.label)}</div>\n          <div class=\"detail-value\">${escapeHtml(f.val || '—')}</div>\n        </div>\n      `).join('');\n\n      // Company Details Cards\n      const companyFields = [\n        { label: 'Company Name', val: formatVal(app.companyName) },\n        { label: 'Company Address', val: formatVal(app.companyAddress), full: true },\n        { label: 'Current Work Exp', val: formatVal(app.currentWorkExp) },\n        { label: 'Total Work Exp', val: formatVal(app.totalWorkExp) },\n        { label: 'Official Mail ID', val: formatVal(app.officialEmail) },\n        { label: 'Office Landline No', val: formatVal(app.officeLandlineNo) },\n      ];\n\n      const cGrid = document.getElementById('company-details-grid');\n      cGrid.innerHTML = companyFields.map(f => `\n        <div class=\"detail-item ${f.full ? 'full-width' : ''}\">\n          <div class=\"detail-label\">${escapeHtml(f.label)}</div>\n          <div class=\"detail-value\">${escapeHtml(f.val || '—')}</div>\n        </div>\n      `).join('');\n\n      // Reference Details Cards\n      const refFields = [\n        { label: 'Ref 1: Name', val: formatVal(app.ref1Name) },\n        { label: 'Ref 1: Mobile No', val: formatVal(app.ref1Mobile) },\n        { label: 'Ref 1: Relation', val: formatVal(app.ref1Relation) },\n        { label: 'Ref 1: Address', val: formatVal(app.ref1Address), full: true },\n        { label: 'Ref 2: Name', val: formatVal(app.ref2Name) },\n        { label: 'Ref 2: Mobile No', val: formatVal(app.ref2Mobile) },\n        { label: 'Ref 2: Relation', val: formatVal(app.ref2Relation) },\n        { label: 'Ref 2: Address', val: formatVal(app.ref2Address), full: true },\n      ];\n\n      const rGrid = document.getElementById('reference-details-grid');\n      rGrid.innerHTML = refFields.map(f => `\n        <div class=\"detail-item ${f.full ? 'full-width' : ''}\">\n          <div class=\"detail-label\">${escapeHtml(f.label)}</div>\n          <div class=\"detail-value\">${escapeHtml(f.val || '—')}</div>\n        </div>\n      `).join('');\n\n      renderDocumentsList(lead.requiredDocs || [], isSubmitted);\n\n      // Submission status handling\n      const lockBanner = document.getElementById('dashboard-locked-banner');\n      const noticeAlert = document.getElementById('dashboard-notice-alert');\n      const actionWrap = document.getElementById('submission-action-wrap');\n      const statusBadge = document.getElementById('portal-status-badge');\n\n      if (isSubmitted) {\n        lockBanner.style.display = 'flex';\n        noticeAlert.style.display = 'none';\n        statusBadge.textContent = '🔒 SUBMITTED & LOCKED';\n        statusBadge.className = 'badge badge-uploaded';\n\n        if (actionWrap) {\n          const dateStr = lead.submittedAt ? new Date(lead.submittedAt).toLocaleString('en-IN') : 'recently';\n          actionWrap.innerHTML = `\n            <div class=\"alert alert-success\" style=\"margin-bottom: 0;\">\n              <span>✓ <strong>Application Locked</strong>: This file was confirmed and submitted on <strong>${dateStr}</strong>. Document modifications are now restricted to authorized loan administrators.</span>\n            </div>\n          `;\n        }\n      }\n    }\n\n    function renderDocumentsList(docs, isLocked = false) {\n      const container = document.getElementById('documents-list-container');\n      const uploadedCount = docs.filter(d => d.isUploaded).length;\n      const totalCount = docs.length;\n\n      document.getElementById('doc-counter-badge').textContent = `${uploadedCount} / ${totalCount} UPLOADED`;\n      document.getElementById('doc-counter-badge').className = `badge ${uploadedCount === totalCount ? 'badge-uploaded' : 'badge-pending'}`;\n\n      const pct = totalCount > 0 ? (uploadedCount / totalCount) * 100 : 0;\n      document.getElementById('doc-progress-fill').style.width = `${pct}%`;\n\n      if (docs.length === 0) {\n        container.innerHTML = `<div style=\"text-align: center; color: var(--text-muted); padding: 24px;\">No specific documents checklist required for this loan category.</div>`;\n        return;\n      }\n\n      container.innerHTML = docs.map(d => {\n        const isUp = d.isUploaded;\n        const upItem = d.uploadedItem;\n        const maxMb = d.maxFileSizeMb || 10;\n        const formats = (d.allowedFormats || ['pdf', 'jpg', 'png']).join(', ').toUpperCase();\n\n        const badgeHtml = isUp\n          ? `<span class=\"badge badge-uploaded\">✓ UPLOADED</span>`\n          : `<span class=\"badge badge-pending\">PENDING</span>`;\n\n        const viewLinkHtml = isUp && upItem && upItem.fileUrl\n          ? `<a href=\"${upItem.fileUrl}\" target=\"_blank\" class=\"btn btn-secondary btn-sm\" style=\"text-decoration:none;\">View File</a>`\n          : '';\n\n        let actionControlHtml = '';\n        if (isLocked) {\n          actionControlHtml = isUp\n            ? `<span style=\"font-size: 13px; font-weight: 700; color: #059669; display: flex; align-items: center; gap: 4px;\">🔒 Locked</span>`\n            : `<span style=\"font-size: 13px; font-weight: 600; color: #94A3B8;\">Submission Closed</span>`;\n        } else {\n          actionControlHtml = `\n            <div class=\"doc-upload-btn-wrap\">\n              <button class=\"btn btn-primary btn-sm\">\n                <span>${isUp ? 'Replace' : 'Upload'}</span>\n              </button>\n              <input type=\"file\" class=\"doc-upload-input\" accept=\".pdf,image/*\" onchange=\"uploadDocument('${d.id}', '${encodeURIComponent(d.name)}', ${maxMb}, '${encodeURIComponent(JSON.stringify(d.allowedFormats || []))}', this)\">\n            </div>\n          `;\n        }\n\n        return `\n          <div class=\"doc-item-card\">\n            <div class=\"doc-item-info\">\n              <div class=\"doc-item-icon ${isUp ? 'uploaded' : ''}\">${isUp ? '✓' : '📄'}</div>\n              <div>\n                <div class=\"doc-item-title\">${escapeHtml(d.name)}</div>\n                <div class=\"doc-item-meta\">\n                  ${isUp && upItem \n                    ? `File: ${escapeHtml(upItem.fileName)} • Uploaded on ${new Date(upItem.uploadedAt).toLocaleDateString()}` \n                    : `Max file size: <strong>${maxMb}MB</strong> • Permitted: ${formats}`}\n                </div>\n              </div>\n            </div>\n\n            <div style=\"display: flex; align-items: center; gap: 12px;\">\n              ${badgeHtml}\n              ${viewLinkHtml}\n              ${actionControlHtml}\n            </div>\n          </div>\n        `;\n      }).join('');\n    }\n\n    // Document Upload with strict file size & format validation\n    async function uploadDocument(docTypeId, docNameEnc, maxMb, allowedFormatsEnc, inputEl) {\n      if (!inputEl.files || inputEl.files.length === 0) return;\n      const file = inputEl.files[0];\n      const docName = decodeURIComponent(docNameEnc);\n\n      // 1. Strict File Size Validation\n      const maxBytes = maxMb * 1024 * 1024;\n      if (file.size > maxBytes) {\n        const fileMb = (file.size / (1024 * 1024)).toFixed(1);\n        showToast(`File size (${fileMb}MB) exceeds the ${maxMb}MB limit for ${docName}.`, true);\n        alert(`File size (${fileMb}MB) exceeds the maximum limit of ${maxMb}MB for \"${docName}\".\\nPlease compress or choose a smaller file.`);\n        inputEl.value = '';\n        return;\n      }\n\n      // 2. Strict Format Validation\n      let allowed = ['pdf', 'jpg', 'jpeg', 'png'];\n      try {\n        allowed = JSON.parse(decodeURIComponent(allowedFormatsEnc)).map(f => f.toLowerCase().replace('.', ''));\n      } catch (_) {}\n\n      const ext = (file.name.split('.').pop() || '').toLowerCase();\n      if (!allowed.includes(ext)) {\n        showToast(`.${ext} format is not allowed. Supported: ${allowed.join(', ').toUpperCase()}`, true);\n        alert(`File format \".${ext}\" is not permitted for \"${docName}\".\\nAllowed formats: ${allowed.join(', ').toUpperCase()}`);\n        inputEl.value = '';\n        return;\n      }\n\n      showToast(`Uploading ${file.name}...`);\n\n      const formData = new FormData();\n      formData.append('document', file);\n      formData.append('docTypeId', docTypeId);\n      formData.append('docName', docName);\n\n      try {\n        const res = await fetch(`${apiBase}/api/crm-public/client-portal/${token}/upload-doc`, {\n          method: 'POST',\n          body: formData,\n        });\n        const data = await res.json();\n        if (!res.ok || !data.success) {\n          throw new Error(data.error || 'Failed to upload document');\n        }\n\n        showToast(`${docName} uploaded successfully!`);\n\n        // Re-verify to refresh state\n        const otp = getEnteredOtp();\n        const refreshRes = await fetch(`${apiBase}/api/crm-public/client-portal/${token}/verify-otp`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ mobile: currentMobile, otp }),\n        });\n        const refreshData = await refreshRes.json();\n        if (refreshData.success && refreshData.data.lead) {\n          applicationData = refreshData.data.lead;\n          renderDocumentsList(applicationData.requiredDocs || [], applicationData.isSubmitted);\n        }\n      } catch (err) {\n        showToast(err.message, true);\n        alert(`Upload error: ${err.message}`);\n      } finally {\n        inputEl.value = '';\n      }\n    }\n\n    // Confirmation Checkbox & Save Application\n    function toggleSubmitBtn() {\n      const chk = document.getElementById('confirm-checkbox');\n      const btn = document.getElementById('btn-submit-portal');\n      if (chk && btn) {\n        btn.disabled = !chk.checked;\n        btn.style.opacity = chk.checked ? '1' : '0.5';\n      }\n    }\n\n    async function submitPortal() {\n      const chk = document.getElementById('confirm-checkbox');\n      if (!chk || !chk.checked) {\n        showToast('Please check the confirmation box before submitting.', true);\n        return;\n      }\n\n      const uploadedCount = (applicationData?.requiredDocs || []).filter(d => d.isUploaded).length;\n      if (uploadedCount === 0) {\n        alert('Please upload at least one required loan document before saving and submitting your application.');\n        return;\n      }\n\n      const confirmed = confirm('Are you sure you want to submit your application?\\n\\nOnce submitted, your application and documents will be LOCKED and forwarded to the administrator. You will not be able to change them directly.');\n      if (!confirmed) return;\n\n      const btn = document.getElementById('btn-submit-portal');\n      btn.disabled = true;\n      btn.innerHTML = '<span class=\"spinner\"></span> <span>Saving & Submitting...</span>';\n\n      try {\n        const res = await fetch(`${apiBase}/api/crm-public/client-portal/${token}/submit`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n        });\n        const data = await res.json();\n        if (!res.ok || !data.success) {\n          throw new Error(data.error || 'Failed to submit application');\n        }\n\n        showToast('Application confirmed and locked successfully!');\n        if (applicationData) {\n          applicationData.isSubmitted = true;\n          applicationData.submittedAt = data.data.submittedAt || new Date().toISOString();\n          renderDashboard(applicationData);\n        }\n      } catch (err) {\n        showToast(err.message, true);\n        alert(`Submission error: ${err.message}`);\n        btn.disabled = false;\n        btn.innerHTML = '<span>Save & Submit Application</span>';\n      }\n    }\n\n    function escapeHtml(str) {\n      if (!str) return '';\n      return String(str)\n        .replace(/&/g, '&amp;')\n        .replace(/</g, '&lt;')\n        .replace(/>/g, '&gt;')\n        .replace(/\"/g, '&quot;')\n        .replace(/'/g, '&#039;');\n    }\n\n    // Explicitly expose globals\n    window.sendOtp = sendOtp;\n    window.verifyOtp = verifyOtp;\n    window.resendOtp = resendOtp;\n    window.uploadDocument = uploadDocument;\n    window.submitPortal = submitPortal;\n    window.toggleSubmitBtn = toggleSubmitBtn;\n\n    // Attach listeners and run initialization\n    function bootstrap() {\n      const sendBtn = document.getElementById('btn-send-otp');\n      if (sendBtn) {\n        sendBtn.addEventListener('click', (e) => {\n          e.preventDefault();\n          sendOtp();\n        });\n      }\n\n      const verifyBtn = document.getElementById('btn-verify-otp');\n      if (verifyBtn) {\n        verifyBtn.addEventListener('click', (e) => {\n          e.preventDefault();\n          verifyOtp();\n        });\n      }\n\n      const resendBtn = document.getElementById('btn-resend-otp');\n      if (resendBtn) {\n        resendBtn.addEventListener('click', (e) => {\n          e.preventDefault();\n          resendOtp();\n        });\n      }\n\n      const submitBtn = document.getElementById('btn-submit-portal');\n      if (submitBtn) {\n        submitBtn.addEventListener('click', (e) => {\n          e.preventDefault();\n          submitPortal();\n        });\n      }\n\n      const chk = document.getElementById('confirm-checkbox');\n      if (chk) {\n        chk.addEventListener('change', toggleSubmitBtn);\n      }\n\n      const mobileInput = document.getElementById('input-mobile');\n      if (mobileInput) {\n        mobileInput.addEventListener('keydown', (e) => {\n          if (e.key === 'Enter') {\n            e.preventDefault();\n            sendOtp();\n          }\n        });\n      }\n\n      initPortal();\n    }\n\n    if (document.readyState === 'loading') {\n      document.addEventListener('DOMContentLoaded', bootstrap);\n    } else {\n      bootstrap();\n    }\n  </script>\n</body>\n</html>\n";
